def kth_smallest_distance(nums: list[int], k: int) -> int:
    nums = sorted(nums)

    def pairs_within(d: int) -> int:          # pairs at distance <= d, two pointers
        count = left = 0
        for right, x in enumerate(nums):
            while x - nums[left] > d:
                left += 1
            count += right - left
        return count

    lo, hi = 0, nums[-1] - nums[0]            # the answer is a distance in [lo, hi]
    while lo < hi:
        mid = (lo + hi) // 2
        if pairs_within(mid) >= k:
            hi = mid
        else:
            lo = mid + 1
    return lo
